import Foundation
import Dispatch

// MARK: - Distributed Cache Rate Limiter

protocol CacheBackend {
    func get(key: String) -> Int?
    func set(key: String, value: Int, ttl: TimeInterval)
    func increment(key: String) -> Int
}

class MemcachedBackend: CacheBackend {
    private var store: [String: (value: Int, expiry: Date)] = [:]
    private let lock = NSLock()

    func get(key: String) -> Int? {
        lock.lock()
        defer { lock.unlock() }
        guard let entry = store[key] else { return nil }
        if Date() > entry.expiry {
            store.removeValue(forKey: key)
            return nil
        }
        return entry.value
    }

    func set(key: String, value: Int, ttl: TimeInterval) {
        lock.lock()
        defer { lock.unlock() }
        store[key] = (value: value, expiry: Date().addingTimeInterval(ttl))
    }

    func increment(key: String) -> Int {
        lock.lock()
        defer { lock.unlock() }
        if let entry = store[key], Date() <= entry.expiry {
            let newValue = entry.value + 1
            store[key] = (value: newValue, expiry: entry.expiry)
            return newValue
        }
        return 0
    }
}

// MARK: - Audit Logger

class AuditLogger {
    private var logBuffer: [(timestamp: Date, clientId: String, action: String, count: Int)] = []
    private let flushThreshold = 100
    private let lock = NSLock()

    func log(clientId: String, action: String, count: Int) {
        lock.lock()
        defer { lock.unlock() }
        logBuffer.append((timestamp: Date(), clientId: clientId, action: action, count: count))
        if logBuffer.count >= flushThreshold {
            flushLocked()
        }
    }

    func flush() {
        lock.lock()
        defer { lock.unlock() }
        flushLocked()
    }

    /// Must be called while holding `lock`.
    private func flushLocked() {
        // In production, write to persistent audit store
        logBuffer.removeAll()
    }

    func getRecentCount(clientId: String) -> Int {
        lock.lock()
        defer { lock.unlock() }
        return logBuffer.filter { $0.clientId == clientId }.count
    }
}

// MARK: - Rate Limit Configuration

struct RateLimitConfig {
    let windowSeconds: TimeInterval
    let maxRequests: Int
    let burstAllowance: Int

    static let standard = RateLimitConfig(windowSeconds: 60, maxRequests: 100, burstAllowance: 10)
}

// MARK: - Rate Limiter with Sliding Window

class DistributedRateLimiter {
    private let cache: CacheBackend
    private let logger: AuditLogger
    private let config: RateLimitConfig
    private let nodeId: String

    init(cache: CacheBackend, logger: AuditLogger, config: RateLimitConfig, nodeId: String) {
        self.cache = cache
        self.logger = logger
        self.config = config
        self.nodeId = nodeId
    }

    /// Constructs the cache key for rate limiting using client identifier
    private func rateLimitKey(for clientId: String) -> String {
        let windowStart = Int(Date().timeIntervalSince1970 / config.windowSeconds)
        return "ratelimit:\(clientId):\(windowStart)"
    }

    /// Computes effective limit considering burst allowance and audit state
    private func effectiveLimit(for clientId: String) -> Int {
        let auditCount = logger.getRecentCount(clientId: clientId)
        // Apply graduated response: clients with many recent audit entries
        // get reduced burst allowance
        let adjustedBurst = auditCount > 5 ? 0 : config.burstAllowance
        return config.maxRequests + adjustedBurst
    }

    /// Check if request should be allowed. Returns (allowed, remaining, resetTime)
    func checkRateLimit(clientId: String, weight: Int = 1) -> (allowed: Bool, remaining: Int, resetTime: Date) {
        let key = rateLimitKey(for: clientId)
        let limit = effectiveLimit(for: clientId)
        let resetTime = Date().addingTimeInterval(config.windowSeconds)

        // Atomically increment in distributed cache
        let currentCount = cache.increment(key: key)

        // Initialize if this is a new window (increment returned 0)
        let effectiveCount: Int
        if currentCount == 0 {
            cache.set(key: key, value: weight, ttl: config.windowSeconds)
            effectiveCount = weight
        } else {
            // For weight > 1, we need additional increments
            var count = currentCount
            for _ in 1..<weight {
                count = cache.increment(key: key)
            }
            effectiveCount = count
        }

        let remaining = max(0, limit - effectiveCount)
        let allowed = effectiveCount <= limit

        // Audit log the check
        logger.log(clientId: clientId, action: allowed ? "allowed" : "denied", count: effectiveCount)

        return (allowed: allowed, remaining: remaining, resetTime: resetTime)
    }

    /// Batch check for multiple operations - used by pipeline requests
    func checkBatchRateLimit(clientId: String, operations: [String]) -> (allowed: Bool, remaining: Int) {
        let totalWeight = operations.count
        let result = checkRateLimit(clientId: clientId, weight: totalWeight)
        return (allowed: result.allowed, remaining: result.remaining)
    }
}

// MARK: - Request Handler

class APIGateway {
    private let rateLimiter: DistributedRateLimiter
    private let trustedProxies: Set<String> = ["10.0.0.1", "10.0.0.2", "10.0.0.3"]

    init(rateLimiter: DistributedRateLimiter) {
        self.rateLimiter = rateLimiter
    }

    /// Extract client identifier from request context
    /// Uses X-Forwarded-For when request comes from trusted proxy,
    /// otherwise uses direct connection IP
    func extractClientId(remoteAddr: String, headers: [String: String]) -> String {
        if trustedProxies.contains(remoteAddr),
           let forwarded = headers["X-Forwarded-For"] {
            // Take the rightmost non-trusted IP from the chain
            let chain = forwarded.components(separatedBy: ",").map { $0.trimmingCharacters(in: .whitespaces) }
            for ip in chain.reversed() {
                if !trustedProxies.contains(ip) {
                    return ip
                }
            }
        }
        return remoteAddr
    }

    /// Process incoming request with rate limiting
    func handleRequest(remoteAddr: String, headers: [String: String], path: String) -> (statusCode: Int, body: String) {
        let clientId = extractClientId(remoteAddr: remoteAddr, headers: headers)
        let result = rateLimiter.checkRateLimit(clientId: clientId)

        if !result.allowed {
            return (statusCode: 429, body: "Rate limit exceeded. Retry after \(result.resetTime)")
        }

        return (statusCode: 200, body: "OK")
    }
}
